package contacts

import (
	"context"
	"os"
	"testing"

	"github.com/Flyozzzz/farlink-server/internal/accounts"
	"github.com/Flyozzzz/farlink-server/internal/federation"
	"github.com/Flyozzzz/farlink-server/internal/wire"
)

// Generated by ContactDeliveryProofTests with FARLINK_WRITE_FIXTURE. The normal
// Go suite always verifies the saved Swift signature against real account chains.
func TestSwiftDeliveryProofIsAccepted(t *testing.T) {
	data, err := os.ReadFile("testdata/swift-delivery.cbor")
	if err != nil {
		t.Fatal(err)
	}
	var fixture struct {
		SenderLinks    [][]byte             `cbor:"sender_links"`
		RecipientLinks [][]byte             `cbor:"recipient_links"`
		Proof          ContactDeliveryProof `cbor:"proof"`
		Envelope       []byte               `cbor:"envelope"`
		Now            uint64               `cbor:"now"`
	}
	if err := wire.Lenient(data, &fixture); err != nil {
		t.Fatal(err)
	}
	registry, err := accounts.Open(t.TempDir())
	if err != nil {
		t.Fatal(err)
	}
	for _, chain := range [][][]byte{fixture.SenderLinks, fixture.RecipientLinks} {
		for _, link := range chain {
			if _, _, err := registry.Submit(link); err != nil {
				t.Fatal(err)
			}
		}
	}
	resolver, err := accounts.OpenResolver(registry, t.TempDir(), nil)
	if err != nil {
		t.Fatal(err)
	}
	proof := fixture.Proof
	if _, err := proof.Check(context.Background(), resolver, fixture.Now); err != nil {
		t.Fatalf("Swift delivery rejected: %v", err)
	}
	request := federation.NewRequest(proof.Origin, proof.DeliveryID, proof.SenderDevice, proof.RecipientDevice,
		proof.Kind, proof.ExpiresAt, fixture.Envelope)
	request.Bytes = uint64(len(fixture.Envelope))
	if !proof.Matches(request) {
		t.Fatal("Swift proof does not match transport")
	}
	request.Envelope = append(request.Envelope, 0)
	if proof.Matches(request) {
		t.Fatal("changed envelope accepted")
	}
	proof.LogicalID = append([]byte(nil), proof.LogicalID...)
	proof.LogicalID[0] ^= 1
	if _, err := proof.Check(context.Background(), resolver, fixture.Now); err == nil {
		t.Fatal("changed logical send accepted")
	}
}
